pts":{"disclosure":"Hello, you've reached Aangan Studio. I'm an automated assistant, and this call may be transcribed so the team can follow up. You can ask for a person at any time.","language_prompt":"Would you prefer to continue in English, Hindi or Marathi?","qualified_close":"Thank you. Your project sounds like the kind our designers take on.","needs_review_close":"Thank you. A member of the team will review your details and call you back.","not_fit_close":"This sounds like it may not be the right fit for us right now, but feel free to reach out if your timeline or scope changes.","booking_offer":"Would you like to book a consultation with a designer?","booking_read_back":"To confirm, you'd like a consultation on {slot_label}. Shall I book it?","booking_confirmed":"Your consultation is booked for {slot_label}.","booking_conflict":"That time has just been taken. Could you choose another time?","booking_pending":"I couldn't confirm that booking just now, so it is not booked yet. The team will call you to arrange a time.","booking_declined":"No problem. A designer will call you to follow up.","handoff_confirmation":"I've passed your details to the team so you won't need to repeat them.","policy_missing_fallback":"Thank you for calling Aangan Studio. I'll take your details and the team will call you back.","recording_declined":"Understood. I won't keep a transcript. I'll take a short message so the team can call you back."},"languages":{"offered":["en","hi","mr"],"provisional":true},"operations":{"staffed_hours":{"days":[1,2,3,4,5,6],"open":"10:00","close":"19:00"},"transfer_available_when_staffed":false,"response_target_seconds":300,"meaningful_response_min_chars":20,"front_desk_queue_email":"front-desk@aangan-demo.example","handoff":{"ack_deadline_minutes":120,"escalate_overdue_to":"front_desk_queue"}},"booking":{"enabled":true,"duration_minutes":45,"horizon_days":7,"max_slots_offered":3,"require_attendee_email":false},"crm":{"sync_decisions":["qualified"]},"retention":{"transcript_days":90,"provider_payload_days":30,"recording_days":30}}$policy$::jsonb, '{"ok": true, "issues": []}'::jsonb, now()
